#!/usr/bin/env python3
"""Assemble the print/println example proofs (examples/proofs-print/<isa>/<Name>.lean) from the
shared fragments in examples/proofs-print/<isa>/src/: every example proves the runtime print
functions it calls from the same lemmas (a proof file must be self-contained: `janus verify`
checks one file against one extraction), so the lemmas live once, in the fragments, and each
example file is their concatenation with the example's own part (src/<Name>.main.lean).

Usage: scripts/gen-print-proofs.py [--check]
  --check   exit 1 if a generated file differs from what the fragments give (the verify scripts
            run this first, so a stale proof file is never verified)."""
import os, sys
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
# the fragments each example needs, in order (its callees' lemmas before their callers')
EXAMPLES = {
    "PrintX":    ["00-head", "10-printlock", "20-recordForPanic", "30-gwrite", "40-printstring",
                  "50-printnl", "70-printuint", "90-lock"],
    "PrintBool": ["00-head", "10-printlock", "20-recordForPanic", "30-gwrite", "40-printstring",
                  "50-printnl", "60-printbool", "90-lock"],
    "PrintNeg":  ["00-head", "10-printlock", "20-recordForPanic", "30-gwrite", "70-printuint",
                  "80-printint", "90-lock"],
    "PrintStr":  ["00-head", "10-printlock", "20-recordForPanic", "30-gwrite", "40-printstring",
                  "50-printnl", "90-lock"],
}
def build(isa, name, frags):
    d = os.path.join(root, "examples", "proofs-print", isa, "src")
    parts = []
    main = os.path.join(d, name + ".main.lean")
    if not os.path.exists(main):
        return None
    mtxt = open(main, encoding="utf-8").read()
    # the main fragment starts with its module doc (after `import Extracted`)
    for f in frags:
        p = os.path.join(d, f + ".lean")
        if os.path.exists(p):
            parts.append(open(p, encoding="utf-8").read().strip("\n"))
    head = parts[0]
    doc = mtxt.split("-- BODY\n", 1)
    pre, body = (doc[0], doc[1]) if len(doc) == 2 else ("", mtxt)
    gen = ("-- Generated by scripts/gen-print-proofs.py from examples/proofs-print/%s/src/ "
           "(%s): edit the fragments, not this file.\n" % (isa, ", ".join(frags + [name + ".main"])))
    head = head.replace("import Extracted\n", "import Extracted\n" + gen + "\n" + pre, 1)
    return "\n\n".join([head] + parts[1:] + [body.strip("\n")]) + "\n\nend Proof\n"
def main():
    check = "--check" in sys.argv[1:]
    bad = 0
    for isa in ("arm64", "amd64"):
        for name, frags in EXAMPLES.items():
            out = build(isa, name, frags)
            if out is None:
                continue
            path = os.path.join(root, "examples", "proofs-print", isa, name + ".lean")
            old = open(path, encoding="utf-8").read() if os.path.exists(path) else None
            if old != out:
                if check:
                    print("stale: %s (run scripts/gen-print-proofs.py)" % os.path.relpath(path, root))
                    bad = 1
                else:
                    open(path, "w", encoding="utf-8").write(out)
                    print("wrote %s" % os.path.relpath(path, root))
    sys.exit(bad)
main()
